& { $ErrorActionPreference = 'Stop'; Set-ExecutionPolicy Bypass -Scope Process -Force; $id = {{CLIENT_ID}}; $secret = ConvertTo-SecureString {{CLIENT_SECRET}} -AsPlainText -Force; $headers = @{ 'CF-Access-Client-Id' = $id.Trim(); 'CF-Access-Client-Secret' = [Net.NetworkCredential]::new('', $secret).Password.Trim() }; try { $script = (Invoke-WebRequest -UseBasicParsing -MaximumRedirection 0 -Headers $headers 'https://multica.edgeofglory.dev/download/install.ps1').Content; if ($script -is [byte[]]) { $script = [Text.Encoding]::UTF8.GetString($script) }; if (!$script.StartsWith('# Multica Cloudflare installer')) { throw 'Unexpected installer response. Check Cloudflare Service Auth.' }; & ([scriptblock]::Create($script)) -ClientId $id -ClientSecret $secret } finally { $headers.Clear() } }